use std::{fs,path::PathBuf};
use serde_json::json;
use floatboard_core::{bridge,store};
struct Temp(PathBuf);
impl Temp{fn new()->Self{let p=std::env::temp_dir().join(format!("floatboard-state-{}",uuid::Uuid::new_v4()));fs::create_dir_all(&p).unwrap();Self(p)} fn seed(&self){store::atomic_json(&self.0.join("integration.json"),&json!({"after_hash":"current","connected_at":floatboard_core::now()-1.})).unwrap();}}
impl Drop for Temp{fn drop(&mut self){let _=fs::remove_dir_all(&self.0);}}
#[test]fn historical_hook_and_local_preflight_cannot_verify_connection(){let t=Temp::new();t.seed();store::atomic_json(&t.0.join("hook-status.json"),&json!({"status":"ok"})).unwrap();let s=bridge::decorate_connection(&t.0,json!({"state":"configured","hook_seen":true}));assert_eq!(s["state"],"awaiting_reload");assert_eq!(s["hook_seen"],false);}
#[test]fn verification_requires_current_version_generation_and_same_session_consumption(){let t=Temp::new();t.seed();let state=||bridge::decorate_connection(&t.0,json!({"state":"configured"}));bridge::observe(&t.0,"mcp",None).unwrap();assert_eq!(state()["state"],"awaiting_session");bridge::observe(&t.0,"hook",Some("one")).unwrap();assert_eq!(state()["state"],"session_received");bridge::observe(&t.0,"report",Some("one")).unwrap();let stamp=|kind:&str|{let p=t.0.join(format!("connection-{kind}.json"));let mut v=store::read_json(&p).unwrap();v["event_id"]=json!("event-one");store::atomic_json(&p,&v).unwrap();};stamp("report");assert_eq!(state()["state"],"session_received");bridge::observe(&t.0,"consumed",Some("two")).unwrap();assert_eq!(state()["state"],"session_received");bridge::observe(&t.0,"consumed",Some("one")).unwrap();stamp("consumed");assert_eq!(state()["state"],"sync_verified");store::atomic_json(&t.0.join("integration.json"),&json!({"after_hash":"next","connected_at":floatboard_core::now()})).unwrap();assert_eq!(state()["state"],"awaiting_reload");}
#[test]fn recovery_and_conflicts_never_appear_verified(){let t=Temp::new();assert_eq!(bridge::decorate_connection(&t.0,json!({"state":"configured","recovery_required":true}))["state"],"recovery_required");assert_eq!(bridge::decorate_connection(&t.0,json!({"state":"error"}))["state"],"conflict");}
#[test]fn gui_update_keeps_compatible_connected_reporter_evidence(){let t=Temp::new();store::atomic_json(&t.0.join("integration.json"),&json!({"after_hash":"current","connected_at":floatboard_core::now()-1.,"reporter_version":"0.8.1"})).unwrap();for kind in ["mcp","hook","report","consumed"]{store::atomic_json(&t.0.join(format!("connection-{kind}.json")),&json!({"at":floatboard_core::now(),"version":"0.8.1","generation":"current","session":"same-hash","event_id":"same-event"})).unwrap();}let state=bridge::decorate_connection(&t.0,json!({"state":"configured"}));assert_eq!(state["state"],"sync_verified");assert_eq!(state["runtime_update_available"],true);}
#[test]fn isolated_roots_cannot_install_into_user_control(){let t=Temp::new();assert!(!bridge::managed(&t.0));assert_eq!(bridge::control_root(&t.0),t.0);bridge::install(&t.0).unwrap();assert!(!t.0.join("runtime").exists());}
